package kz.bekzat.jwt.dao;
import kz.bekzat.jwt.db.DatabaseConnection; import kz.bekzat.jwt.model.*; import org.springframework.stereotype.Repository; import java.sql.*; import java.util.Optional;
@Repository public class UserDao { private final DatabaseConnection db; public UserDao(DatabaseConnection db){this.db=db;} public void save(AppUser u){try(Connection c=db.open();PreparedStatement p=c.prepareStatement("INSERT INTO users VALUES(?,?,?,?,?)")){p.setString(1,u.getId());p.setString(2,u.getUsername());p.setString(3,u.getPasswordHash());p.setString(4,u.getRole().name());p.setString(5,u.getCreatedAt().toString());p.executeUpdate();}catch(SQLException e){throw new IllegalStateException("Cannot save user: "+e.getMessage(),e);}} public Optional<AppUser> findByUsername(String name){try(Connection c=db.open();PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE username=?")){p.setString(1,name);try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();return Optional.of(new AppUser(r.getString("id"),r.getString("username"),r.getString("password_hash"),Role.valueOf(r.getString("role")),java.time.Instant.parse(r.getString("created_at"))));}}catch(SQLException e){throw new IllegalStateException(e);}} }
